    private static int delta(int a,int b){return Math.abs((a>>16&255)-(b>>16&255))+Math.abs((a>>8&255)-(b>>8&255))+Math.abs((a&255)-(b&255));}
    public static List<Icon> detect(int[] px,int w,int h){
        List<Icon> result=new ArrayList<>();
        if(px==null || px.length!=w*h || w<180 || h<w*1.5)return result;
        // All five recordings show a single three-slot vertical stack. Icons
        // move between slots; never equate a slot number with a skill type.
        double scale=w/480.0;
        for(double yy:new double[]{.728,.809,.890}){
            Icon best=null;
            for(int dx=-7;dx<=7;dx+=2)for(int dy=-7;dy<=7;dy+=2){
                int x=(int)Math.round(w*.271+dx*scale),y=(int)Math.round(h*yy+dy*scale);
                for(Template t:TEMPLATES){
                    int sum=0,i=0;
                    for(int b=-6;b<=6;b++)for(int a=-6;a<=6;a++)if(a*a+b*b<=36){
                        int xx=x+(int)Math.round(a*3*scale),yy2=y+(int)Math.round(b*3*scale);
                        sum+=delta(px[yy2*w+xx],t.colors[i++]);
                    }
                    double err=sum/(3.0*i);
                    if(best==null || err<best.error)best=new Icon(t.kind,x,y,err);
                }
            }
            // Strict threshold rejects empty charging slots, reward animations,
            // and unrecognized artwork; it is not a probability.
            if(best!=null && best.error<22)result.add(best);
        }
        return result;
    }
    public static Icon find(List<Icon> icons,Kind kind){for(Icon icon:icons)if(icon.kind==kind)return icon;return null;}
